effect.shader:
mat2 rotate2D(float r){ return mat2(cos(r), sin(r), -sin(r), cos(r)); }
void main(){
vec2 R = acLayerSize;
vec2 uv = (acLayerNorm * R - 0.5 * R) / max(R.y, 1.0);
vec3 col = vec3(0.0);
float t = acTime * TIME_SPEED;
vec2 n = vec2(0.0);
vec2 q = vec2(0.0);
vec2 p = uv;
float d = dot(p, p);
float S = S0;
float aAcc = 0.0;
mat2 m = rotate2D(ROT);
int iters = int(clamp(ITER, 1.0, 64.0));
for (int j = 0; j < 64; j++){
if (j < iters) {
p = m * p;
n = m * n;
q = p * S + t * 4.0 + sin(t * 4.0 - d * 6.0) * 0.8 + float(j) + n;
aAcc += dot(cos(q) / S, vec2(0.2));
n -= sin(q);
S *= S_GROW;
}
}
vec3 cm = COLOR_MUL.rgb;
col = cm * (aAcc + ADD_BIAS) + aAcc + aAcc - d * POST_SUB_D;
col = pow(max(col, 0.0), vec3(GAMMA));
gl_FragColor = vec4(col, 1.0);
}
